return {
	-- Guide
	-- {spell:768} Cat Form
	["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Deine Tarn- und Nahkampfgestalt: In Forever gibt diese Questreihe {spell:768} auf Stufe 20, nicht der Lehrer.",

	-- Step 1: Cenarion Enclave
	-- {npc:4217} Mathrengyl Bearwalker · {area:1658} Cenarion Enclave · {zone:1457} Darnassus · {spell:18960} Teleport: Moonglade · {npc:11800} Silva Fil'naveth · {area:2361} Nighthaven · {area:702} Rut'theran Village · {npc:11802} Dendrite Starblaze · {area:493} Moonglade
	["{npc:4217} stands in the {area:1658}. Skyborne far from {zone:1457}: cast {spell:18960} and take {npc:11800}'s flight from the middle of {area:2361} (she flies druids to {area:702}, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to {npc:11802}, and its Trial of the Lake (the Aquatic Form guide) is in the same {area:493}."] = "{npc:4217} steht in der {area:1658}. Himmelsgeborene weit weg von {zone:1457}: Wirke {spell:18960} und nimm den Flug von {npc:11800} aus der Mitte von {area:2361} (sie fliegt Druiden nach {area:702}, keine Flugroute nötig), dann das Portal nach oben. Noch keine Wassergestalt? Nimm bei ihm auch A Lesson to Learn an: Sie geht ebenfalls an {npc:11802}, und ihre Trial of the Lake (der Wassergestalt-Guide) liegt im selben {area:493}.",

	-- Step 3: Dendrite Starblaze
	-- {spell:18960} Teleport: Moonglade · {npc:11802} Dendrite Starblaze · {area:2361} Nighthaven
	["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it."] = "",

	-- Step 4: The relics of the Barrow Dens
	["The relics of the Barrow Dens"] = "Die Relikte der Grabhügel",
	-- {quest:98394} The Great Cat Spirit · {area:493} Moonglade · {npc:272054} Avatar of Saeyleenan · {area:2361} Nighthaven · {area:2363} Stormrage Barrow Dens
	["{quest:98394} (Night Elves) waits on the hill above the bridge in southern {area:493}; the {npc:272054} (Skyborne) stands on high ground past the twin bridges, south-west of {area:2361}: climb up to it. The relics lie in the {area:2363} east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more."] = "{quest:98394} (Nachtelfen) wartet auf dem Hügel über der Brücke im Süden von {area:493}; der {npc:272054} (Himmelsgeborene) steht auf einer Anhöhe hinter den Zwillingsbrücken, südwestlich von {area:2361}: Klettere zu ihm hinauf. Die Relikte liegen in {area:2363} östlich des Sees: Verlasse deine Gestalt und klicke die Statue am Eingang der Höhle an, um kurz getarnt zu sein (fünf Minuten), und geh dann tief in die Höhle und über die Brücke. Wütende Geister bewachen die Relikte und greifen alles an, was sie sehen: Bleib in der Tarnung der Statue und bewege dich weiter. Jedes Relikt ist eine kleine Kugel neben einer Katzenstatue in einer Nische: Fang und Claw haben je einen Platz, Silent Shadow zwei, und dort campen die Spieler. Ein Relikt wird als unbenutzbar angezeigt, während ein anderer Spieler es plündert: Warte kurz und versuche es erneut. Tarnung weg? Geh zurück zur Statue am Eingang, um eine neue zu bekommen.",

	-- Step 5: Back to Dendrite Starblaze
	-- {npc:11802} Dendrite Starblaze
	["Back to {npc:11802}"] = "Zurück zu {npc:11802}",
	-- {spell:18960} Teleport: Moonglade · {npc:11802} Dendrite Starblaze · {area:2361} Nighthaven · {npc:11800} Silva Fil'naveth · {area:702} Rut'theran Village
	["Cast {spell:18960} to land by {npc:11802} in {area:2361} (nobody on Zephras Isle takes the Skyborne quest), then take {npc:11800}'s flight to {area:702}: she stands in the middle of {area:2361} and flies druids there, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Wirke {spell:18960}, um bei {npc:11802} in {area:2361} zu landen (niemand auf Zephras Isle nimmt die Himmelsgeborenen-Quest an), und nimm dann den Flug von {npc:11800} nach {area:702}: Sie steht in der Mitte von {area:2361} und fliegt Druiden dorthin, keine Flugroute nötig. {npc:11802} steht oben in seinem Gebäude: Geh drinnen nach oben, der Pfeil kann die Stockwerke nicht unterscheiden.",

	-- Step 6: Cenarion Enclave
	-- {npc:4217} Mathrengyl Bearwalker · {area:1658} Cenarion Enclave · {spell:768} Cat Form
	["Take the portal up to {npc:4217}, upstairs in the {area:1658}: he teaches you {spell:768}."] = "Nimm das Portal nach oben zu {npc:4217}, oben in der {area:1658}: Er bringt dir {spell:768} bei.",

